        "id": "worldlabs-frameboy-atlas",
        "source_lang": "en",
        "eyebrow": "AI NEWS",
        "tool": "Games",
        "source": "World Labs",
        "url": "https://www.worldlabs.ai/blog/atlas-realtime",
